import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Contracts & OpenAPI 3.1","description":"","frontmatter":{},"headers":[],"relativePath":"en/04-contracts-and-openapi.md","filePath":"en/04-contracts-and-openapi.md"}'),s={name:"en/04-contracts-and-openapi.md"};function o(r,e,c,d,p,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="contracts-openapi-3-1" tabindex="-1">Contracts &amp; OpenAPI 3.1 <a class="header-anchor" href="#contracts-openapi-3-1" aria-label="Permalink to &quot;Contracts &amp; OpenAPI 3.1&quot;">​</a></h1><blockquote><p><strong>End-to-End Type Safety and Code Generation</strong><br><em>FastAPI, Pydantic v2, Orval, and TanStack Query.</em></p></blockquote><hr><h2 id="_1-universal-source-of-truth" tabindex="-1">1. Universal Source of Truth <a class="header-anchor" href="#_1-universal-source-of-truth" aria-label="Permalink to &quot;1. Universal Source of Truth&quot;">​</a></h2><p>In SoftForge, the frontend never writes loose types or hardcoded URLs. All network contracts derive directly from the <strong>OpenAPI 3.1.0</strong> specification exported from backend Pydantic models.</p><hr><h2 id="_2-cold-static-extraction-export-openapi-py" tabindex="-1">2. Cold Static Extraction (<code>export_openapi.py</code>) <a class="header-anchor" href="#_2-cold-static-extraction-export-openapi-py" aria-label="Permalink to &quot;2. Cold Static Extraction (`export_openapi.py`)&quot;">​</a></h2><p>No running database or live web server is needed to inspect or export API contracts. The script <code>tools/scripts/export_openapi.py</code> statically instantiates the FastAPI app with an in-memory test engine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/scripts/export_openapi.py</span></span></code></pre></div><p>This updates <code>apps/api/openapi.json</code> in milliseconds.</p><hr><h2 id="_3-automated-frontend-codegen-orval" tabindex="-1">3. Automated Frontend CodeGen (<code>Orval</code>) <a class="header-anchor" href="#_3-automated-frontend-codegen-orval" aria-label="Permalink to &quot;3. Automated Frontend CodeGen (`Orval`)&quot;">​</a></h2><p>SoftForge integrates <strong>Orval</strong> directly into the frontend build and development lifecycle.</p><h3 id="automatic-execution-on-dev-and-build" tabindex="-1">Automatic Execution on <code>dev</code> and <code>build</code> <a class="header-anchor" href="#automatic-execution-on-dev-and-build" aria-label="Permalink to &quot;Automatic Execution on `dev` and `build`&quot;">​</a></h3><p>Whenever you run either script in <code>apps/web/</code>, Orval is automatically triggered before Vite or TypeScript compilation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In development (runs codegen and launches Vite HMR)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In production build (runs codegen, runs tsc typecheck, and bundles)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or on-demand:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codegen</span></span></code></pre></div><p>Orval produces:</p><ul><li><strong>Strictly Typed TypeScript Models</strong> in <code>apps/web/src/api/generated/models/</code>.</li><li><strong>TanStack Query Hooks</strong> (<code>useQuery</code>, <code>useMutation</code>) for each backend operation with built-in caching and reactive loading/error states.</li><li><strong>Configured Axios Client</strong> (<code>apps/web/src/lib/api-client.ts</code>) with <code>withCredentials: true</code> for HttpOnly cookies and authorization interceptors.</li></ul><hr><h2 id="_4-git-policy-quality-assurance" tabindex="-1">4. Git Policy &amp; Quality Assurance <a class="header-anchor" href="#_4-git-policy-quality-assurance" aria-label="Permalink to &quot;4. Git Policy &amp; Quality Assurance&quot;">​</a></h2><ul><li><strong>Ignored in Version Control:</strong> The directory <code>apps/web/src/api/generated/</code> is included in <code>.gitignore</code> to keep the Git history clean of machine-generated code.</li><li><strong>Gatekeeper Validation (<code>verify.py</code>):</strong> The script <code>tools/scripts/verify.py</code> runs <code>npm run typecheck</code>, immediately catching any schema discrepancies between backend and frontend before code is merged.</li></ul>',21)])])}const k=a(s,[["render",o]]);export{u as __pageData,k as default};
